 const create=async e=>{e.preventDefault();setSaving(true);try{const f=new FormData(e.target);await api.post('/admin/teams',{hackathonId:h._id,name:f.get('name'),leaderId:f.get('leaderId'),memberIds:f.getAll('memberIds')});setCreateOpen(false);e.target.reset();reload();setMsg('Team created successfully. It remains incomplete until it reaches the minimum size.')}catch(e){setMsg(e.response?.data?.message||'Could not create team')}finally{setSaving(false)}};
