 const removeMember=async(t,m)=>{if(!confirm(`Remove ${m.name} from ${t.name}?`))return;try{await api.delete('/admin/teams/'+t._id+'/members/'+m._id);reload();setMsg('Member removed.')}catch(e){setMsg(e.response?.data?.message||'Could not remove member')}};
